class LexerState:
    START = "START"
    IN_TAG = "IN_TAG"
    IN_VALUE = "IN_VALUE"
    ERROR = "ERROR"

class Token:
    def __init__(self, tag: str, value: str):
        self.tag = tag
        self.value = value
    def __repr__(self):
        return f"Token({self.tag!r}, {self.value!r})"

class LexError(Exception):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.position = position

class ActionTagLexer:
    """Stub lexer. Replace with actual implementation."""
    def __init__(self, input_text: str):
        self.input_text = input_text
        self.position = 0
        self.state = LexerState.START
        self.tokens: List[Token] = []

    def tokenize(self) -> List[Token]:
        """Simulates a state machine. Invariant: must not raise unhandled exceptions."""
        while self.position < len(self.input_text):
            char = self.input_text[self.position]
            if self.state == LexerState.START:
                if char.isalpha():
                    self.state = LexerState.IN_TAG
                    self._start_token = self.position
                elif char.isspace() or char == '\n':
                    self.position += 1
                else:
                    self.state = LexerState.ERROR
                    raise LexError(f"Unexpected character {char!r}", self.position)
            elif self.state == LexerState.IN_TAG:
                if char == ':':
                    self._tag = self.input_text[self._start_token:self.position]
                    self.state = LexerState.IN_VALUE
                    self._value_start = self.position + 1
                elif not (char.isalnum() or char == '_'):
                    self.state = LexerState.ERROR
                    raise LexError(f"Invalid tag character {char!r}", self.position)
                self.position += 1
            elif self.state == LexerState.IN_VALUE:
                if char == '\n':
                    value = self.input_text[self._value_start:self.position].strip()
                    self.tokens.append(Token(self._tag, value))
                    self.state = LexerState.START
                self.position += 1
            else:
                raise RuntimeError("Invalid state")
        # Handle end of input
        if self.state == LexerState.IN_VALUE:
            value = self.input_text[self._value_start:self.position].strip()
            self.tokens.append(Token(self._tag, value))
            self.state = LexerState.START
        elif self.state == LexerState.IN_TAG:
            raise LexError("Unterminated tag", self.position)
        return self.tokens


class IdentityParser:
    """Stub parser. Replace with actual implementation."""
    def __init__(self, input_text: str):
        self.input_text = input_text

    def parse(self) -> dict:
        """Simulates parsing. Invariant: must consume all input or raise typed error."""
        if not self.input_text.startswith("[IDENTITY_LOCK]"):
            raise ValueError("Missing identity lock header")
        # Find closing bracket
        end_idx = self.input_text.find("]", 1)
        if end_idx == -1:
            raise ValueError("Unterminated identity lock")
        # Extract fields (simplified)
        fields = {}
        for line in self.input_text[end_idx+1:].split("\n"):
            if ":" in line:
                key, value = line.split(":", 1)
                fields[key.strip()] = value.strip()
        return fields


# --- UNIT TESTS: Action Tag Lexer ---

class TestActionTagLexerUnit:
    def test_single_valid_tag(self):
        lexer = ActionTagLexer("WRITE_FILE: test.txt\n")
        tokens = lexer.tokenize()
        assert len(tokens) == 1
        assert tokens[0].tag == "WRITE_FILE"
        assert tokens[0].value == "test.txt"

    def test_multiple_tags(self):
        lexer = ActionTagLexer("WRITE_FILE: a.txt\nDELEGATE_TASK: QA | Run tests\n")
        tokens = lexer.tokenize()
        assert len(tokens) == 2
        assert tokens[0].tag == "WRITE_FILE"
        assert tokens[1].tag == "DELEGATE_TASK"

    def test_empty_value(self):
        lexer = ActionTagLexer("WRITE_FILE:\n")
        tokens = lexer.tokenize()
        assert len(tokens) == 1
        assert tokens[0].value == ""

    def test_whitespace_handling(self):
        lexer = ActionTagLexer("  WRITE_FILE:   spaced.txt  \n")
        tokens = lexer.tokenize()
        assert tokens[0].value == "spaced.txt"

    def test_invalid_start_character(self):
        lexer = ActionTagLexer("12345\n")
        with pytest.raises(LexError):
            lexer.tokenize()

    def test_unterminated_tag(self):
        lexer = ActionTagLexer("WRITE_FILE")
        with pytest.raises(LexError):
            lexer.tokenize()

    def test_invalid_tag_character(self):
        lexer = ActionTagLexer("WRITE-FILE: test.txt\n")
        with pytest.raises(LexError):
            lexer.tokenize()

    def test_empty_input(self):
        lexer = ActionTagLexer("")
        assert lexer.tokenize() == []

    def test_only_newlines(self):
        lexer = ActionTagLexer("\n\n\n")
        assert lexer.tokenize() == []


