class TestLexerStateMachineInvariants:
    """Fuzzing the lexer to ensure state-machine invariants hold."""

    @given(st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=200))
    @settings(max_examples=1000, suppress_health_check=[HealthCheck.too_slow])
    def test_lexer_never_crashes_unexpectedly(self, input_text: str):
        """Invariant: The lexer must either produce tokens or raise LexError, never anything else."""
        lexer = ActionTagLexer(input_text)
        try:
            tokens = lexer.tokenize()
            # If we get here, tokens must be a list of Token objects
            assert isinstance(tokens, list)
            for token in tokens:
                assert isinstance(token, Token)
                assert isinstance(token.tag, str)
                assert isinstance(token.value, str)
        except LexError as e:
            # LexError is acceptable, but must have a position
            assert isinstance(e.position, int)
            assert 0 <= e.position <= len(input_text)
        except Exception as e:
            pytest.fail(f"Unexpected exception type: {type(e).__name__}: {e}")

    @given(st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=100))
    @settings(max_examples=500)
    def test_lexer_error_state_is_terminal(self, input_text: str):
        """Invariant: Once an error occurs, no further tokens are produced."""
        lexer = ActionTagLexer(input_text)
        try:
            tokens = lexer.tokenize()
            # If no error, all is well
            assert isinstance(tokens, list)
        except LexError:
            # After an error, the lexer should be in ERROR state
            assert lexer.state == LexerState.ERROR

    @given(st.lists(st.text(alphabet=string.ascii_letters + "_", min_size=1, max_size=10), min_size=1, max_size=10),
           st.lists(st.text(max_size=50), min_size=1, max_size=10))
    @settings(max_examples=200)
    def test_lexer_roundtrip(self, tags: List[str], values: List[str]):
        """Property: Tokenizing a validly formatted input yields the expected tokens."""
        assume(len(tags) == len(values))
        input_text = ""
        for tag, value in zip(tags, values):
            input_text += f"{tag}: {value}\n"
        lexer = ActionTagLexer(input_text)
        tokens = lexer.tokenize()
        assert len(tokens) == len(tags)
        for token, tag, value in zip(tokens, tags, values):
            assert token.tag == tag
            assert token.value == value


