# --- PERFORMANCE / STRESS SIMULATION ---

class TestPerformance:
    """Basic performance sanity checks."""

    def test_large_input_performance(self):
        """Lexer should handle 10k lines without excessive time."""
        import time
        lines = ["WRITE_FILE: file_{}.txt\n".format(i) for i in range(10000)]
        input_text = "".join(lines)
        start = time.time()
        lexer = ActionTagLexer(input_text)
        tokens = lexer.tokenize()
        elapsed = time.time() - start
        assert len(tokens) == 10000
        # Allow generous time for CI environments
        assert elapsed < 5.0, f"Lexer took {elapsed:.2f}s for 10k lines"

    def test_parser_large_input_performance(self):
        """Parser should handle large identity blocks."""
        import time
        fields = "\n".join([f"Field_{i}: value_{i}" for i in range(1000)])
        input_text = f"[IDENTITY_LOCK]\n{fields}\n"
        start = time.time()
        parser = IdentityParser(input_text)
        result = parser.parse()
        elapsed = time.time() - start
        assert len(result) == 1000
        assert elapsed < 2.0, f"Parser took {elapsed:.2f}s for 1000 fields"


